    n=int(tag[0]); l='spdfg'.index(tag[1]); return n,l
viol=[]; tie=[]
for r in rows:
    Z=r['Z']; od=[(t,D) for t,D in r['order'] if D is not None]
    for i in range(len(od)):
        for j in range(i+1,len(od)):
            (ta,Da),(tb,Db)=od[i],od[j]   # Da <= Db, a wins over b
            na,la=nl(ta); nb,lb=nl(tb)
            sa,sb=na+la,nb+lb
            if sa>sb: viol.append((Z,ta,tb,round(Da,5),round(Db,5)))
            elif sa==sb and na>nb: tie.append((Z,ta,tb,round(Da,5),round(Db,5)))
print('rows audited',len(rows))
print('ORDERING violations (larger n+l beats smaller):',len(viol))
for v in viol[:10]: print('  ',v)
print('TIE-BREAK violations (higher n beats lower at equal n+l):',len(tie))
for v in tie[:20]: print('  ',v)
"

